def test_campaign_summary_no_sessions(groups):
    assert campaign_summary(groups, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_campaign_summary_counts_each_session_without_deduplication():
    event = {"id": "same", "day": 1, "converted": True}
    assert campaign_summary({"a": [event, event], "b": [event]}, 1) == {
        "rate": 1.0, "recent": 3, "groups": 2,
    }


